package top.pxczxn.community.analytics.application; import com.baomidou.mybatisplus.core.toolkit.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import top.pxczxn.community.analytics.model.CreatorAnalyticsEvent; import top.pxczxn.community.analytics.persistence.CreatorAnalyticsEventMapper; import top.pxczxn.community.article.model.Article; import top.pxczxn.community.article.persistence.ArticleMapper; import top.pxczxn.community.blog.model.Blog; import top.pxczxn.community.blog.persistence.BlogMapper; import top.pxczxn.community.shared.auth.CommunityAuth; import top.pxczxn.platform.common.exception.BusinessException; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor public class CreatorAnalyticsService { private final CommunityAuth auth; private final ArticleMapper articleMapper; private final BlogMapper blogMapper; private final CreatorAnalyticsEventMapper events;
 @Transactional(readOnly=true) public CreatorAnalyticsView mine(Integer rawDays){int days=rawDays==null?30:rawDays;if(days<7||days>365)throw new BusinessException(400,"统计天数应为 7-365");Long user=auth.getLoginUserId();List<Article> articles=articleMapper.selectList(Wrappers.<Article>lambdaQuery().eq(Article::getAuthorUserId,user).eq(Article::getPublishStatus,"PUBLISHED").isNull(Article::getDeletedAt));long views=articles.stream().mapToLong(a->n(a.getViewCount())).sum(),likes=articles.stream().mapToLong(a->n(a.getLikeCount())).sum(),favorites=articles.stream().mapToLong(a->n(a.getFavoriteCount())).sum(),comments=articles.stream().mapToLong(a->n(a.getCommentCount())).sum(); long followers=blogMapper.selectList(Wrappers.<Blog>lambdaQuery().eq(Blog::getOwnerUserId,user).eq(Blog::getStatus,"ACTIVE").isNull(Blog::getDeletedAt)).stream().mapToLong(b->n(b.getFollowerCount())).sum();LocalDateTime from=LocalDateTime.now().minusDays(days);return new CreatorAnalyticsView(articles.size(),views,likes,favorites,comments,followers,events.daily(user,from).stream().map(x->new CreatorAnalyticsView.DailyMetric(String.valueOf(x.get("day")),n(x.get("count")))).toList(),articles.stream().sorted(Comparator.comparingLong((Article a)->n(a.getViewCount())+n(a.getLikeCount())+n(a.getFavoriteCount())+n(a.getCommentCount())).reversed()).limit(10).map(a->new CreatorAnalyticsView.ArticlePerformance(a.getId(),a.getTitle(),n(a.getViewCount()),n(a.getLikeCount()),n(a.getFavoriteCount()),n(a.getCommentCount()))).toList(),metrics(events.sources(user,from),"source"),metrics(events.terms(user,from),"term")); }
 @Transactional public void track(Long articleId,String source,String term){Article article=articleMapper.selectById(articleId);if(article==null||article.getDeletedAt()!=null||!"PUBLISHED".equals(article.getPublishStatus())||!"PUBLIC".equals(article.getVisibility()))throw new BusinessException(404,"文章不存在");String s=source==null?"DIRECT":source.trim().toUpperCase(Locale.ROOT);if(!Set.of("DIRECT","INTERNAL","SEARCH","REFERRAL").contains(s))s="DIRECT";CreatorAnalyticsEvent e=new CreatorAnalyticsEvent();e.setId(IdWorker.getId());e.setArticleId(articleId);e.setAuthorUserId(article.getAuthorUserId());e.setEventType(term==null||term.isBlank()?"VIEW":"SEARCH_CLICK");e.setSourceType(s);e.setSearchTerm(term==null?null:term.trim().substring(0,Math.min(80,term.trim().length())));e.setOccurredAt(LocalDateTime.now());events.insert(e);}
 private static List<CreatorAnalyticsView.CountMetric> metrics(List<Map<String,Object>> values,String key){return values.stream().map(x->new CreatorAnalyticsView.CountMetric(String.valueOf(x.get(key)),n(x.get("count")))).toList();}private static long n(Object v){return v instanceof Number x?x.longValue():v==null?0:Long.parseLong(v.toString());} }
